mapper.select:
SELECT A.MST_NO AS id, A.SEQ AS seq, 'STATUS_CD' + A.STATUS_CD AS className, F.GBN_NAME AS gbn_name, A.TITLE AS title, CONVERT(varchar(10), CONVERT(date, A.SC_DATE, 112), 23) AS start, CONVERT(varchar(10), CONVERT(date, A.SC_DATE, 112), 23) AS [end] FROM dbo.TWK_SCHEDULE_NEW A LEFT JOIN dbo.TWK_SCHEDULE_GBN AS F ON(A.OFFICE_CODE = F.OFFICE_CODE AND A.SCH_GBN = F.SCH_GBN) WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND A.SC_DATE >= #{start} AND A.SC_DATE <= #{end}
UNION SELECT 99999999 AS id, 99999999 AS seq, 'absent' AS className, '근태' AS gbn_name, C.NAME + '(' + D.ABSENT_NAME + ')' AS title, CONVERT(varchar(10), CONVERT(date, B.START_DATE, 112), 23) AS start, CONVERT(varchar(10), CONVERT(date, B.END_DATE, 112), 23) AS [end] FROM dbo.TAD_ABSENT AS B LEFT JOIN dbo.TAD_EMP AS C ON B.OFFICE_CODE = C.OFFICE_CODE AND B.EMP_NO = C.EMP_NO LEFT JOIN dbo.TAD_ABSENT_ITEM AS D ON B.ABSENT_CD = D.ABSENT_CD AND B.OFFICE_CODE = D.OFFICE_CODE WHERE B.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND B.START_DATE >= #{start} AND B.END_DATE <= #{end}
UNION SELECT 0 AS id, 0 AS seq, 'holiday' AS className, '공휴일' AS gbn_name, E.H_NAME AS title, CONVERT(varchar(10), CONVERT(date, E.H_DATE, 112), 23) AS start, CONVERT(varchar(10), CONVERT(date, E.H_DATE, 112), 23) AS [end] FROM dbo.TPM_HOLY AS E WHERE 1 = 1
AND E.H_DATE >= #{start} AND E.H_DATE <= #{end}
ORDER BY id

update.if:
UPDATE A SET A.TITLE = U.TITLE, A.DESCR = U.DESCR, A.MAIN_DEPT_CD = U.MAIN_DEPT_CD, A.SCH_GBN = U.SCH_GBN, A.STATUS_CD = U.STATUS_CD, A.WORK_USER_ID = U.WORK_USER_ID, A.WORKER_NAME = U.WORKER_NAME FROM dbo.TWK_SCHEDULE_NEW A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.SC_DATE} AS SC_DATE, #{row.MST_NO} AS MST_NO, #{row.MST_MONTH} AS MST_MONTH, #{row.TITLE} AS TITLE, #{row.DESCR} AS DESCR, #{row.SCH_GBN} AS SCH_GBN, #{row.MAIN_DEPT_CD} AS MAIN_DEPT_CD, #{row.STATUS_CD} AS STATUS_CD, #{row.WORK_USER_ID} AS WORK_USER_ID, #{row.WORKER_NAME} AS WORKER_NAME
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.SC_DATE = U.SC_DATE AND A.MST_NO = U.MST_NO AND A.MST_MONTH = U.MST_MONTH

mapper.delete:
DELETE FROM dbo.TWK_SCHEDULE_NEW WHERE EXISTS ( SELECT 1 FROM (
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.SC_DATE} AS SC_DATE, #{row.MST_MONTH} AS MST_MONTH, #{row.MST_NO} AS MST_NO, #{row.SEQ} AS SEQ
) AS temp WHERE temp.OFFICE_CODE = TWK_SCHEDULE_NEW.OFFICE_CODE AND temp.SC_DATE = TWK_SCHEDULE_NEW.SC_DATE AND temp.MST_MONTH = TWK_SCHEDULE_NEW.MST_MONTH AND temp.MST_NO = TWK_SCHEDULE_NEW.MST_NO AND temp.SEQ = TWK_SCHEDULE_NEW.SEQ )

mapper.select:
SELECT
	A.MST_NO					AS MST_NO,
	A.MST_MONTH					AS MST_MONTH,
	A.SEQ						AS SEQ,
	A.SC_DATE					AS SC_DATE,
	A.TITLE						AS TITLE,
	A.SCH_GBN					AS SCH_GBN,
	B.GBN_NAME      			AS GBN_NAME,
	A.MAIN_DEPT_CD				AS MAIN_DEPT_CD,
	C.DEPT_NAME 				AS MAIN_DEPT_NAME,
	A.STATUS_CD					AS STATUS_CD,
	dbo.getCode_nm(A.STATUS_CD) as STATUS_NM
FROM dbo.TWK_SCHEDULE_NEW A
LEFT JOIN dbo.TWK_SCHEDULE_GBN AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SCH_GBN = B.SCH_GBN
LEFT JOIN dbo.THR_DEPT AS C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MAIN_DEPT_CD = C.DEPT_CD
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}

		AND A.SC_DATE >= #{START_DATE}


		AND A.SC_DATE  <= #{END_DATE}


		AND A.SC_DATE >= #{START_DATE}
		AND A.SC_DATE  <= #{END_DATE}


		AND A.SCH_GBN = #{SCH_GBN}


		AND A.MAIN_DEPT_CD = #{MAIN_DEPT_CD}


		AND A.STATUS_CD = #{STATUS_CD}


		A.TITLE LIKE '%' + #{TEXT} + '%' OR A.DESCR LIKE '%' + #{TEXT} + '%'

SELECT A.MST_NO AS MST_NO, A.MST_MONTH AS MST_MONTH, A.SEQ AS SEQ, A.SC_DATE AS SC_DATE, A.TITLE + CHAR(13) + CHAR(10) + CONVERT(VARCHAR(MAX), A.DESCR) AS TITLE, A.SCH_GBN AS SCH_GBN, B.GBN_NAME AS GBN_NAME, A.MAIN_DEPT_CD AS MAIN_DEPT_CD, C.DEPT_NAME AS MAIN_DEPT_NAME, A.STATUS_CD AS STATUS_CD, dbo.getCode_nm(A.STATUS_CD) AS STATUS_NM, CASE WHEN NULLIF(LTRIM(RTRIM(D.NAME)), '') IS NULL THEN WORKER_NAME ELSE D.NAME END AS WORKER_NAME FROM dbo.TWK_SCHEDULE_NEW A LEFT JOIN dbo.TWK_SCHEDULE_GBN AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SCH_GBN = B.SCH_GBN LEFT JOIN dbo.THR_DEPT AS C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MAIN_DEPT_CD = C.DEPT_CD LEFT JOIN dbo.TAD_EMP AS D ON A.OFFICE_CODE = D.OFFICE_CODE AND A.WORK_USER_ID = D.EMP_NO AND (NULLIF(LTRIM(RTRIM(D.RESIGN_DATE)), '') IS NULL OR CONVERT(DATE, D.RESIGN_DATE, 112) >= CAST(GETDATE() AS DATE)) WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND A.SC_DATE >= #{START_DATE}
AND A.SC_DATE <= #{END_DATE}
AND A.SC_DATE >= #{START_DATE} AND A.SC_DATE <= #{END_DATE}
AND A.STATUS_CD = #{STATUS_CD}

SELECT A.MST_NO AS MST_NO, A.MST_MONTH AS MST_MONTH, A.SEQ AS SEQ, A.SC_DATE AS SC_DATE, A.TITLE + CHAR(13) + CHAR(10) + CONVERT(VARCHAR(MAX), A.DESCR) AS TITLE, A.SCH_GBN AS SCH_GBN, B.GBN_NAME AS GBN_NAME, A.MAIN_DEPT_CD AS MAIN_DEPT_CD, C.DEPT_NAME AS MAIN_DEPT_NAME, A.STATUS_CD AS STATUS_CD, dbo.getCode_nm(A.STATUS_CD) AS STATUS_NM, CASE WHEN NULLIF(LTRIM(RTRIM(D.NAME)), '') IS NULL THEN WORKER_NAME ELSE D.NAME END AS WORKER_NAME FROM dbo.TWK_SCHEDULE_NEW A LEFT JOIN dbo.TWK_SCHEDULE_GBN AS B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SCH_GBN = B.SCH_GBN LEFT JOIN dbo.THR_DEPT AS C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MAIN_DEPT_CD = C.DEPT_CD LEFT JOIN dbo.TAD_EMP AS D ON A.OFFICE_CODE = D.OFFICE_CODE AND A.WORK_USER_ID = D.EMP_NO AND (NULLIF(LTRIM(RTRIM(D.RESIGN_DATE)), '') IS NULL OR CONVERT(DATE, D.RESIGN_DATE, 112) >= CAST(GETDATE() AS DATE)) WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
AND A.SC_DATE >= #{START_DATE}
AND A.STATUS_CD = #{STATUS_CD}

